
from taf.gnb.oam.coam.vdu.releases.vduoam23r3 import vDuOAM23R3
from taf.gnb.oam.coam.vdu.schemas.fh.get_1d_weight_data_response import Operation
from taf.gnb.oam.coam.vdu.schemas.fh.get_beam_data_response import GetBeamDataResponse
from taf.gnb.oam.coam.vdu.schemas.fh.get_direction_data_response import GetDirectionDataResponse
from taf.gnb.oam.coam.vdu.schemas.fh.get_weight_data_response import GetWeightDataResponse
from taf.gnb.oam.coam.vdu.schemas.fh.get_1d_weight_data_response import Get1dWeightDataResponse
from taf.gnb.oam.coam.vdu.schemas.fh.get_antenna_parameters_response import GetAntennaParametersResponse
from taf.gnb.oam.coam.vdu.utilities.use_m2m_parser import enforce_use_m2m_type
from taf.gnb.oam.coam.vdu.schemas.asm_licensed.diagnostic_info_from_sfp_connection_v2 import \
    DiagnosticInfoFromSFPConnectionASMV1LICENSEDV2
from taf.gnb.oam.coam.vdu.services.trs_licensed.trs_licensed_v1 import TRSLicensedV1
from taf.gnb.oam.coam.vdu.schemas.trs_v2.get_ssh_tunnel_config_detail_v2 import GetSshTunnelConfigDetail
from taf.gnb.oam.coam.vdu.schemas.asm.get_serviceuser_sync_status_response import GetServiceuserSyncStatusResponse
from taf.gnb.oam.coam.vdu.schemas.asm.get_serviceuser_info_v1 import GetServiceuserInfoV1


class vDuOAM23R4(vDuOAM23R3):
    def __init__(self, con_details, need_all_info=False):
        super(vDuOAM23R4, self).__init__(con_details, need_all_info)
        self.trs_licensed_v1 = TRSLicensedV1(con_details)

    def upload_weight_factor_file(self, weight_file_path, target_dn, timeout=30):
        response = self.fh_v1.upload_weight_factor_file(weight_file_path=weight_file_path, target_dn=target_dn,
                                                        timeout=timeout)
        return Operation.from_object_dict(response)

    def get_upload_weight_factor_file_operation(self, operation_id, timeout=30, raw=False):
        response = self.fh_v1.get_upload_weight_factor_file_operation(operation_id=operation_id, timeout=timeout)
        return response if raw else Operation.from_object_dict(response)

    def delete_upload_weight_factor_file_operation(self, operation_id, timeout=30):
        return self.fh_v1.delete_upload_weight_factor_file_operation(operation_id=operation_id, timeout=timeout)

    def trigger_to_get_beam_data(self, target_dn, low_frequency, high_frequency, timeout=30):
        response = self.fh_v1.trigger_to_get_beam_data(target_dn=target_dn, low_frequency=low_frequency,
                                                       high_frequency=high_frequency, timeout=timeout)
        return Operation.from_object_dict(response)

    def get_beam_data_operation(self, operation_id, timeout=30, raw=False):
        response = self.fh_v1.get_beam_data_operation(operation_id=operation_id, timeout=timeout)
        return response if raw else GetBeamDataResponse.from_object_dict(response)

    def delete_get_beam_data_operation(self, operation_id, timeout=30):
        return self.fh_v1.delete_get_beam_data_operation(operation_id=operation_id, timeout=timeout)

    def trigger_to_get_direction_data(self, target_dn, low_frequency, high_frequency, horizontal_beamwidth,
                                      vertical_beamwidth, timeout=30):
        response = self.fh_v1.trigger_to_get_direction_data(target_dn=target_dn, low_frequency=low_frequency,
                                                            high_frequency=high_frequency,
                                                            horizontal_beamwidth=horizontal_beamwidth,
                                                            vertical_beamwidth=vertical_beamwidth, timeout=timeout)
        return Operation.from_object_dict(response)

    def get_direction_data_operation(self, operation_id, timeout=30, raw=False):
        response = self.fh_v1.get_direction_data_operation(operation_id=operation_id, timeout=timeout)
        return response if raw else GetDirectionDataResponse.from_object_dict(response)

    def delete_get_direction_data_operation(self, operation_id, timeout=30):
        return self.fh_v1.delete_get_direction_data_operation(operation_id=operation_id, timeout=timeout)

    def trigger_to_get_weight_data(self, target_dn, low_frequency, high_frequency, horizontal_beamwidth,
                                   vertical_beamwidth, azimuth, tilt, timeout=30):
        response = self.fh_v1.trigger_to_get_weight_data(target_dn=target_dn, low_frequency=low_frequency,
                                                         high_frequency=high_frequency,
                                                         horizontal_beamwidth=horizontal_beamwidth,
                                                         vertical_beamwidth=vertical_beamwidth, azimuth=azimuth,
                                                         tilt=tilt, timeout=timeout)
        return Operation.from_object_dict(response)

    def get_weight_data_operation(self, operation_id, timeout=30, raw=False):
        response = self.fh_v1.get_weight_data_operation(operation_id=operation_id, timeout=timeout)
        return response if raw else GetWeightDataResponse.from_object_dict(response)

    def delete_get_weight_data_operation(self, operation_id, timeout=30):
        return self.fh_v1.delete_get_weight_data_operation(operation_id=operation_id, timeout=timeout)

    def restore_weight_factors_to_default_values(self, target_dn, timeout=30):
        response = self.fh_v1.restore_weight_factors_to_default_values(target_dn=target_dn, timeout=timeout)
        return Operation.from_object_dict(response)

    def get_operation_state_of_restoring_weight_factors(self, operation_id, timeout=30, raw=False):
        response = self.fh_v1.get_operation_state_of_restoring_weight_factors(operation_id=operation_id, timeout=timeout)
        return response if raw else Operation.from_object_dict(response)

    def delete_operation_of_restoring_weight_factors(self, operation_id, timeout=30):
        return self.fh_v1.delete_operation_of_restoring_weight_factors(operation_id=operation_id, timeout=timeout)

    def read_sensor_data(self, target_dn, timeout=30):
        response = self.fh_v1.read_sensor_data(target_dn=target_dn, timeout=timeout)
        return Operation.from_object_dict(response)

    def get_operation_of_reading_sensor_data(self, operation_id, timeout=30, raw=False):
        response = self.fh_v1.get_operation_of_reading_sensor_data(operation_id=operation_id, timeout=timeout)
        return response if raw else Operation.from_object_dict(response)

    def delete_read_sensor_data_operation(self, operation_id, timeout=30):
        return self.fh_v1.delete_read_sensor_data_operation(operation_id=operation_id, timeout=timeout)

    def trigger_get_1d_weight_data(self, target_dn, electrical_tilt, broadcast_beam_width, low_frequency, high_frequency,
                                   timeout=30):
        response = self.fh_v1.trigger_get_1d_weight_data(target_dn=target_dn, electrical_tilt=electrical_tilt,
                                                         broadcast_beam_width=broadcast_beam_width,
                                                         low_frequency=low_frequency, high_frequency=high_frequency,
                                                         timeout=timeout)
        return Operation.from_object_dict(response)

    def get_1d_weight_data(self, operation_id, timeout=30, raw=False):
        response = self.fh_v1.get_1d_weight_data(operation_id=operation_id, timeout=timeout)
        return response if raw else Get1dWeightDataResponse.from_object_dict(response)

    def delete_get_1d_weight_data_operation(self, operation_id, timeout=30):
        return self.fh_v1.delete_get_1d_weight_data_operation(operation_id=operation_id, timeout=timeout)

    def get_rae_antenna_parameters(self, target_dn, timeout=30):
        response = self.fh_v1.get_rae_antenna_parameters(target_dn=target_dn, timeout=timeout)
        return GetAntennaParametersResponse.from_object_dict(response)

    def trigger_cell_groups_reset(self, dist_name, graceful_cell_shutdown=False, timeout=30):
        response = self.cp_config_licensed.trigger_cell_groups_reset(dist_name=dist_name,
                                                                     graceful_cell_shutdown=graceful_cell_shutdown,
                                                                     timeout=timeout)
        return Operation.from_object_dict(response)

    def get_operation_of_reset_cell_group(self, operation_id, timeout=30, raw=False):
        response = self.cp_config_licensed.get_operation_of_reset_cell_group(operation_id=operation_id,
                                                                             timeout=timeout)
        return response if raw else Operation.from_object_dict(response)

    def delete_operation_of_reset_cell_group(self, operation_id, timeout=30):
        return self.cp_config_licensed.delete_operation_of_reset_cell_group(operation_id=operation_id, timeout=timeout)

    @enforce_use_m2m_type
    def get_diagnostic_info_from_sfp_connections(self, request_timeout=30, use_m2m=True, raw=False):
        if use_m2m:
            res = self.asm_licensed.get_diagnostic_info_from_sfp_connections(request_timeout=request_timeout)
        else:
            res = self.asm_v1.get_diagnostic_info_from_sfp_connections(request_timeout=request_timeout)
        return res if raw else DiagnosticInfoFromSFPConnectionASMV1LICENSEDV2.from_object_dict(res)

    @enforce_use_m2m_type
    def config_ssh_tunnel(self, dist_name, operation, timeout=30, use_m2m=True):
        if use_m2m:
            return self.trs_licensed_v1.config_ssh_tunnel(dist_name=dist_name, operation=operation, timeout=timeout)
        else:
            return self.trs_v2.config_ssh_tunnel(dist_name=dist_name, operation=operation, timeout=timeout)

    @enforce_use_m2m_type
    def get_ssh_tunnel_config(self, ssh_mode_type, timeout=30, use_m2m=True):
        if use_m2m:
            response = self.trs_licensed_v1.get_ssh_tunnel_config(ssh_mode_type=ssh_mode_type, timeout=timeout)
        else:
            response = self.trs_v2.get_ssh_tunnel_config(ssh_mode_type=ssh_mode_type, timeout=timeout)
        return GetSshTunnelConfigDetail.from_object_dict(response)

    @enforce_use_m2m_type
    def trigger_serviceuser_sync(self, sync_type, timeout=30, use_m2m=True):
        if use_m2m:
            response = self.asm_licensed.trigger_serviceuser_sync(sync_type=sync_type, timeout=timeout)
        else:
            response = self.asm_v1.trigger_serviceuser_sync(sync_type=sync_type, timeout=timeout)
        return response.operation_id

    @enforce_use_m2m_type
    def get_operation_of_serviceuser_sync_status(self, operation_id, timeout=30, use_m2m=True):
        if use_m2m:
            response = self.asm_licensed.get_operation_of_serviceuser_sync_status(operation_id=operation_id,
                                                                                  timeout=timeout)
        else:
            response = self.asm_v1.get_operation_of_serviceuser_sync_status(operation_id=operation_id, timeout=timeout)
        return GetServiceuserSyncStatusResponse.from_object_dict(response)

    @enforce_use_m2m_type
    def delete_operation_of_serviceuser_sync_status(self, operation_id, timeout=30, use_m2m=True):
        if use_m2m:
            return self.asm_licensed.delete_operation_of_serviceuser_sync_status(operation_id=operation_id,
                                                                                 timeout=timeout)
        else:
            return self.asm_v1.delete_operation_of_serviceuser_sync_status(operation_id=operation_id, timeout=timeout)

    def get_serviceuser_info(self, timeout=30):
        response = self.asm_v1.get_serviceuser_info(timeout=timeout)
        return GetServiceuserInfoV1.from_object_dict(response)
